\textbf{Proposition: } P(n) \text{ is true for all integers } n \ge ${1:1}.

\textbf{1. Base Case } (n = ${1:1}):
\begin{aligned}
\text{LHS} &= ${2:1} \\
\text{RHS} &= ${3:1} \\
\text{LHS} &= \text{RHS} \implies P(${1:1}) \text{ is true.}
\end{aligned}

\textbf{2. Inductive Hypothesis:}
\text{Assume } P(k) \text{ is true for some integer } k \ge ${1:1}, \text{ i.e., } ${4:\sum_{r=1}^k r = \frac{k(k+1)}{2}}.

\textbf{3. Inductive Step } (n = k + 1):
\begin{aligned}
\text{LHS}_{k+1} &= ${4:\sum_{r=1}^k r} + (k + 1) \\
&= ${5:\frac{k(k+1)}{2} + (k + 1)} = ${6:\frac{(k+1)(k+2)}{2}} = \text{RHS}_{k+1}
\end{aligned}

\textbf{Conclusion:}
\text{Since } P(${1:1}) \text{ is true and } P(k) \implies P(k+1), \text{ by mathematical induction } P(n) \text{ holds } \forall n \ge ${1:1}.
